entries[101816] = { ["name"] = "Arkanschlag", ["text"] = "40 Meter Reichweite\nWirken in 2.5 sek.\nÜberzieht das Ziel mit Energie und verursacht 20700 to 25300 Arkanschaden. Jedes Mal, wenn Ihr 'Arkanschlag' wirkt, wird der Schaden von Arkanzaubern um 10% erhöht und die Zauberzeit um 10% verringert. Der Effekt ist bis zu 4-mal stapelbar und hält 6 Sek. lang an." }
