entries[102984] = { ["name"] = "Suchende Schatten", ["text"] = "Unbegrenzte Reichweite\nSofort\nFeuert ein Geschoss auf ein zufälliges Ziel ab. Wenn das Geschoss trifft, fügt es allen Gegnern im Umkreis von 8 Metern um den Zielort 48750 to 51250 Schattenschaden zu." }
